using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Stops the downloading of a file. If a file has already been downloaded, does nothing
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> CancelDownloadFileAsync(int fileId = default, bool onlyIfPending = default)
    {

           using var activity =  StartCallActivity("CancelDownloadFileAsync", typeof(CancelDownloadFile).FullName ?? "CancelDownloadFileAsync");

           try
           {
             return client.CancelDownloadFileAsync(fileId, onlyIfPending);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
// REUSE-IgnoreEnd